SELECT id, name, description, enabled, action_type, condition_json, operation_mode, repeat_interval_seconds, max_repeats, max_notifications_per_window, rollup_window_seconds, escalate_after_seconds, escalate_to_action_id, config_json, created_by, created_time, updated_by, updated_time FROM sentinel_action
AND enabled = #{enabled}
ORDER BY name

SELECT lease_name, node_id, acquired_time, expires_time
FROM sentinel_node_lease
WHERE lease_name = #{leaseName}

mapper.update:
UPDATE sentinel_node_lease
SET expires_time = #{expiresTime}
WHERE lease_name = #{leaseName} AND node_id = #{nodeId}

